template<class F>bool rejects(F f){try{f();return false;}catch(const std::exception&){return true;}}
ColorPreparationInput input(const Scene &s){const auto &o=s.objects().front();return {o.painted,o.appearance,o.material_bindings,o.deformation,o.material};}
Image image(uint32_t r,std::array<uint8_t,4> c){Image out{r,r,std::vector<uint8_t>(size_t(r)*r*4)};for(size_t at=0;at<out.rgba.size();++at)out.rgba[at]=c[at%4];return out;}
BakedTextures bake(uint32_t r,std::array<uint8_t,4> common,std::array<uint8_t,4> pbr,uint8_t coverage){BakedTextures b;b.maps.color=image(r,common);b.maps.metal_rough=image(r,{255,128,0,255});b.maps.emission=image(r,{0,0,0,255});b.coverage.assign(size_t(r)*r,coverage);b.maps.pbr_color=image(r,pbr);b.color_interpretation=BakedColorInterpretation::ResolvedPbr;return b;}
std::array<float,4> value(const Image &i){auto at=size_t(i.width/2)*i.width*4+size_t(i.width/2)*4;std::array<float,4> out;for(size_t c=0;c<4;++c){out[c]=i.rgba[at+c]/255.f;if(c<3)out[c]=srgb_to_linear(out[c]);}return out;}
